{
  "id": "V043",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "지역별 생활 장면에 맞는 광고 이미지 초안 준비 목적이 보존됨."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "이미지 후보를 만들고 담당자가 검토하는 흐름이 보존됨."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "생활용품 광고 이미지와 제품 사진이 보존됨."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "승인된 제품 사진을 입력으로 사용하는 내용이 보존됨."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "배경 장면을 달리한 광고 이미지 후보가 보존됨."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "제품 외형과 브랜드 표현을 유지하고 성능 변경 및 새 효능 문구 추가를 제외하며, 게시는 승인 뒤에 진행함."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능을 추가하지 않음."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "담당자가 후보를 검토하고 실제 게시는 승인 뒤에 진행하는 역할 구분이 보존됨."
    }
  ],
  "issues": [],
  "permission_interpretation": "이미지 후보 생성은 검토를 위한 준비이며, 실제 광고 게시는 승인 뒤에 진행한다는 뜻이다. 후보 생성 주체나 승인 담당자의 구체적 역할은 단정하지 않는다."
}
